/* ═══════════════════════════════════════════════════════════
 * AnimeTV Logger — Unified logging with [ANIMETV] prefix
 * Usage:
 *   Log.i("HOME", "loaded", data)   → [ANIMETV][HOME] loaded {...}
 *   Log.w("NET", "timeout")         → [ANIMETV][NET] timeout
 *   Log.e("API", "failed", err)     → [ANIMETV][API] failed Error...
 *   Log.d("PLAY", "state", obj)     → [ANIMETV][PLAY] state {...}  (debug only)
 *
 * Log levels: ERROR=0, WARN=1, INFO=2, DEBUG=3
 * Set Log.level = Log.LEVELS.WARN to suppress info/debug
 * ═══════════════════════════════════════════════════════════ */
var Log = (function() {
  var LEVELS = { ERROR: 0, WARN: 1, INFO: 2, DEBUG: 3 };
  var PREFIX = "[ANIMETV]";
  var currentLevel = LEVELS.DEBUG; /* show all by default */

  function _fmt(tag) {
    return tag ? PREFIX + "[" + tag + "]" : PREFIX;
  }

  function _log(level, method, tag, args) {
    if (level > currentLevel) return;
    var prefix = _fmt(tag);
    /* Android WebView logcat only reliably shows a SINGLE string argument.
       Concatenate everything into one string so the full message appears. */
    var parts = [prefix];
    for (var i = 0; i < args.length; i++) {
      var a = args[i];
      if (a === null) parts.push("null");
      else if (a === undefined) parts.push("undefined");
      else if (typeof a === "object") {
        try { parts.push(JSON.stringify(a)); } catch(e2) { parts.push(String(a)); }
      } else {
        parts.push(String(a));
      }
    }
    try { console[method](parts.join(" ")); } catch(e) {}
  }

  return {
    LEVELS: LEVELS,
    level: currentLevel,

    /** Info — general operational messages */
    i: function(tag) {
      var args = [];
      for (var i = 1; i < arguments.length; i++) args.push(arguments[i]);
      _log(LEVELS.INFO, "log", tag, args);
    },

    /** Warn — potential issues, non-critical */
    w: function(tag) {
      var args = [];
      for (var i = 1; i < arguments.length; i++) args.push(arguments[i]);
      _log(LEVELS.WARN, "warn", tag, args);
    },

    /** Error — something went wrong */
    e: function(tag) {
      var args = [];
      for (var i = 1; i < arguments.length; i++) args.push(arguments[i]);
      _log(LEVELS.ERROR, "error", tag, args);
    },

    /** Debug — verbose, development-only */
    d: function(tag) {
      var args = [];
      for (var i = 1; i < arguments.length; i++) args.push(arguments[i]);
      _log(LEVELS.DEBUG, "log", tag, args);
    },

    /** Set log level dynamically */
    setLevel: function(lvl) {
      currentLevel = lvl;
      this.level = lvl;
    }
  };
})();

