/* AniList Status Banner Management */
/* AniList Response Cache — Phase 8h: delegated to AnimeTV.cache (localStorage w/ TTL) */
var _anilist_cache = {
  _makeKey: function(q, vars){
    var key = q.replace(/\s+/g,' ').trim() + '|' + JSON.stringify(vars||{});
    var hash = 0;
    for (var i = 0; i < key.length; i++){
      var c = key.charCodeAt(i);
      hash = ((hash << 5) - hash) + c;
      hash = hash & hash;
    }
    return 'anilist:' + Math.abs(hash).toString(36);
  },
  set: function(q, vars, data){
    var key = this._makeKey(q, vars);
    window.AnimeTV.cache.set(key, data, 3600000); /* 1 hour TTL */
  },
  get: function(q, vars){
    var key = this._makeKey(q, vars);
    return window.AnimeTV.cache.get(key);
  },
  isMutation: function(q){
    return q.trim().indexOf('mutation') === 0;
  }
};

var _anilist_status = {
failCount: 0,
  threshold: 2,
  bannerShown: false,
  bannerDismissed: false,
  /* DPAD focus-trap state. The app routes ALL keys through _API.keycb and
   * preventDefault()s handled keys, so native tabindex/focus never fires.
   * When the banner is captured we take over _API.keycb and restore the
   * previous handler on release. */
  _keyPrevCb: null,
  _keyCaptured: false,
  _focusIndex: 0, /* 0 = Retry, 1 = Close */
  showBanner: function(){
    return;
    if (this.bannerShown || this.bannerDismissed) return;
    this.bannerShown = true;
    var el = document.getElementById('anilist_status_banner');
    if (!el) {
      el = document.createElement('div');
      el.id = 'anilist_status_banner';
      el.className = 'anilist-banner-hidden';
      el.innerHTML = '<c>warning</c>' +
        '<span>AniList is temporarily unavailable. Some sections may not load.</span>' +
        '<button id="anilist_banner_retry" tabindex="0">Retry</button>' +
        '<c id="anilist_banner_close" tabindex="0">close</c>';
      document.body.appendChild(el);
      /* Retry button handler — does NOT hide banner; only onSuccess() hides it */
      document.getElementById('anilist_banner_retry').addEventListener('click', function(){
        _anilist_status.failCount = 0;
        /* Force reload the homepage data — banner stays until AniList responds OK */
        if (typeof home !== 'undefined' && app.init_homepage) {
          app.init_homepage(true);
        }
      });
      /* Close/dismiss button handler */
      document.getElementById('anilist_banner_close').addEventListener('click', function(){
        _anilist_status.bannerDismissed = true;
        _anilist_status.releaseKeys();
        _anilist_status.hideBanner();
      });
    }
    /* Show the banner and capture DPAD focus so it can be actioned/dismissed
     * with a remote. */
    setTimeout(function(){
      el.classList.remove('anilist-banner-hidden');
      _anilist_status.captureKeys();
    }, 50);
  },
  /* --- DPAD focus trap --------------------------------------------------- */
  captureKeys: function(){
    if (this._keyCaptured) return;
    if (typeof _API === 'undefined' || !_API.setKey) return;
    this._keyCaptured = true;
    this._keyPrevCb = _API.keycb;
    this._focusIndex = 0;
    this._renderFocus();
    _API.setKey(function(key){ return _anilist_status.handleKey(key); });
  },
  releaseKeys: function(){
    if (!this._keyCaptured) return;
    this._keyCaptured = false;
    if (typeof _API !== 'undefined' && _API.setKey) {
      _API.setKey(this._keyPrevCb);
    }
    this._keyPrevCb = null;
    this._clearFocus();
  },
  handleKey: function(key){
    /* KLEFT=37, KUP=38, KRIGHT=39, KDOWN=40, KENTER=13, KBACK=27 */
    if (key === 37 || key === 38) { this._focusIndex = 0; this._renderFocus(); return true; }
    if (key === 39 || key === 40) { this._focusIndex = 1; this._renderFocus(); return true; }
    if (key === 13) { this._activateFocused(); return true; }
    if (key === 27) { /* Back dismisses the banner */
      this.bannerDismissed = true;
      this.releaseKeys();
      this.hideBanner();
      return true;
    }
    return false;
  },
  _activateFocused: function(){
    var id = this._focusIndex === 1 ? 'anilist_banner_close' : 'anilist_banner_retry';
    var btn = document.getElementById(id);
    if (btn) btn.click();
  },
  _renderFocus: function(){
    var retry = document.getElementById('anilist_banner_retry');
    var close = document.getElementById('anilist_banner_close');
    if (retry) retry.classList.toggle('anilist-banner-focus', this._focusIndex === 0);
    if (close) close.classList.toggle('anilist-banner-focus', this._focusIndex === 1);
  },
  _clearFocus: function(){
    var retry = document.getElementById('anilist_banner_retry');
    var close = document.getElementById('anilist_banner_close');
    if (retry) retry.classList.remove('anilist-banner-focus');
    if (close) close.classList.remove('anilist-banner-focus');
  },
  /* ---------------------------------------------------------------------- */
  hideBanner: function(){
    this.bannerShown = false;
    this.releaseKeys();
    var el = document.getElementById('anilist_status_banner');
    if (el) el.classList.add('anilist-banner-hidden');
  },
  onSuccess: function(){
    this.failCount = 0;
    /* Always hide banner on success, even if user dismissed it earlier */
    if (this.bannerShown || this.bannerDismissed) {
      this.hideBanner();
      this.bannerDismissed = false;
    }
  },
  onFail: function(){
    this.failCount++;
    if (this.failCount >= this.threshold) {
      this.showBanner();
    }
  }
};


/* ======================== Jikan Fallback (bridge-delegated, Phase 8g) ======================== */
var _jikan_fallback = {
  isAnilistDown: function(){
    return (typeof _anilist_status !== 'undefined' && _anilist_status.failCount > 0);
  },

  /* Only handle read queries, not mutations */
  canHandle: function(q){
    if (!q) return false;
    if (q.trim().indexOf('mutation') === 0) return false;
    return true;
  },

  /**
   * Parse the GraphQL query + vars and route to AnimeTV bridge.
   * Delegates to window.AnimeTV.getTrending/getSchedule/getRelated
   * which use the clean architecture Jikan datasource.
   */
  handleQuery: function(q, vars, cb){
    var qs = q.replace(/\s+/g,' ').trim();
    var B = window.AnimeTV;
    if (!B || !B.getTrending){
      cb(null);
      return true;
    }

    /* Trending / Home */
    if (qs.indexOf('TRENDING_DESC') !== -1 && qs.indexOf('RELEASING') !== -1){
      var page = (vars && vars.page) ? vars.page : 1;
      var perPage = (vars && vars.perPage) ? vars.perPage : 10;
      B.getTrending(page, perPage).then(function(result){
        if (!result){ cb(null); return; }
        cb({data:{Page:{pageInfo: result.pageInfo, media: result.media}}});
      }).catch(function(){ cb(null); });
      return true;
    }

    /* Schedule / Airing */
    if (qs.indexOf('airingSchedules') !== -1 || qs.indexOf('airingAt_greater') !== -1){
      B.getSchedule().then(function(result){
        if (!result){ cb(null); return; }
        cb({data:{Page:{pageInfo: result.pageInfo, airingSchedules: result.airingSchedules}}});
      }).catch(function(){ cb(null); });
      return true;
    }

    /* Related + Recommendations (by media id) */
    if (vars && vars.id && qs.indexOf('relations') !== -1 && qs.indexOf('recommendations') !== -1){
      B.getRelated(vars.id).then(function(result){
        if (!result){ cb(null); return; }
        cb({data:{Media:{
          id: result.id,
          idMal: result.id,
          relations: {nodes: result.relations},
          recommendations: {nodes: result.recommendations}
        }}});
      }).catch(function(){ cb(null); });
      return true;
    }

    if (vars && vars.id && qs.indexOf('Media(id:$id') !== -1){
      var media = _MAL && _MAL.aldata ? _MAL.aldata['anilistmedia_' + vars.id] : null;
      if (media){
        cb({data:{Media: media}});
        return true;
      }
    }

    /* Recently aired (weekStart/weekEnd) - reuse schedule */
    if (vars && ('weekStart' in vars || 'weekEnd' in vars)){
      B.getSchedule().then(function(result){
        if (!result){ cb(null); return; }
        cb({data:{Page:{pageInfo: result.pageInfo, airingSchedules: result.airingSchedules}}});
      }).catch(function(){ cb(null); });
      return true;
    }

    /* Popular/Top list - reuse trending */
    if (qs.indexOf('POPULARITY_DESC') !== -1 || qs.indexOf('SCORE_DESC') !== -1){
      var pg = (vars && vars.page) ? vars.page : 1;
      var pp = (vars && vars.perPage) ? vars.perPage : 12;
      B.getTrending(pg, pp).then(function(result){
        if (!result){ cb(null); return; }
        cb({data:{Page:{pageInfo: result.pageInfo, media: result.media}}});
      }).catch(function(){ cb(null); });
      return true;
    }

    /* Queries not supported via bridge - return null */
    cb(null);
    return true;
  }
};
/* ======================== End Jikan Fallback ======================== */

