const __SD_NAME = __SD+". "+(__SOURCE_NAME[__SD-1]);
var __SD_DOMAIN = "";
function SD_CHECK_DOMAIN(sd,cb){
  /* Phase 8c: fully bridged domain check */
  var domains=window.AnimeTV.getDomainsForSource(sd);
  if (!domains || domains.length===0){
    return false;
  }
  var chkCfg=window.AnimeTV.getDomainCheckConfig(sd);
  var chk_url=chkCfg?chkCfg.url:'/manifest.json';
  var chk_json=chkCfg?chkCfg.jsonKey:'name';
  var res=[];
  var num=domains.length;
  function do_test(dm,u,c,i,tstart){
    res[i]={
      dn:dm,
      st:0,
      tm:-1
    };
    if (dm.endsWith('.local') || dm === 'anime.local' || sd === 8){
      res[i]={
        dn:dm,
        st:2,
        tm:0
      };
      if (--num<1){
        if (cb){
          cb(JSON.parse(JSON.stringify(res)));
        }
        Log.d("DOMAIN", "TEST RESULT", res);
      }
      return;
    }
    $ap(u,function(r){
      var rv={
        dn:dm,
        st:1,
        tm:$tick()-tstart
      };
      /* Accept any response with valid JSON containing the expected key
         (some sources like Miruro return 410 with valid JSON body) */
      if (r.responseText){
        try{
          var jv=JSON.parse(r.responseText);
          if (c in jv){
            rv.st=2;
          }
        }catch(e){}
      }
      res[i]=rv;
      if (--num<1){
        if (cb){
          cb(JSON.parse(JSON.stringify(res)));
        }
        Log.d("DOMAIN", "TEST RESULT", res);
      }
    },{"X-Fixdomain-Prox":"1"}).timeout=4000;
  }
  for (var i=0;i<domains.length;i++){
    do_test(domains[i],"https://"+domains[i]+chk_url,chk_json,i,$tick());
  }
  return true;
}
