function SD_SETTINGS(n, cb){
  $('popupcontainer').className='active';
  $('aboutpopup').className='active'; 
  $('popup_qrcode').onclick=null;
  $('popup_qrcode').innerHTML='Benchmarking...';
  $('popup_qrcode').style.display='';
  SD_CHECK_DOMAIN(n,function(r){
    app.settings.close_qrcode();
    $('popup_qrcode').innerHTML='';
    var list_info=[];
    var sid=0;
    var sid_time=60000;
    for (var i=0;i<r.length;i++){
      var w=r[i];
      var tx=special(w.dn)+'<span class="value">'+(w.st==2?("OK - "+w.tm+"ms"):"ERROR")+'</span>';
      if (w.st==2){
        if (w.tm<sid_time){
          sid=i;
          sid_time=w.tm;
        }
      }
      list_info.push(tx);
    }
    var nx=n-1;
    listOrder.showList(
      "Select Source Domain",list_info,
      sid,
      function(chval){
        if (chval!=null){
          var wsel=r[chval];
          if (wsel.st!=2){
            if (!_API.confirmDialog("Domain Warning!!",
            "Target Domain <b>"+wsel.dn+"</b> is failed in benchmark!!!<br>"+
            "Do you want to continue?",
            true)){
              return;
            }
          }
          var sdomain="";
          var _domains=window.AnimeTV.getDomainsForSource(n);
          if (chval>0 && _domains){
            sdomain=_domains[chval];
          }
          _JSAPI.storeSet(SD_CFGNAME(n),sdomain);
          var _toastMsg="Domain changed to: "+(_domains?_domains[chval]:"default");
          /* Store pending toast in case page reloads */
          _JSAPI.storeSet("__pending_toast",_toastMsg);
          _API.showToast(_toastMsg);
          if (cb){
            cb(_domains?_domains[chval]:"");
          }
          return;
        }
        if (cb){
          cb(null);
        }
      },
      true,
      '',
      true
    );
  });
}
function SD_AUTO_SELECT(n, cb){
  /* Instant switch: use previously saved or first available domain, then benchmark in background */
  var _domains=window.AnimeTV.getDomainsForSource(n);
  var savedDomain=_JSAPI.storeGet(SD_CFGNAME(n),"");
  if (!savedDomain && _domains && _domains.length){
    savedDomain=_domains[0];
  }
  /* Save domain immediately so the source switch uses it */
  _JSAPI.storeSet(SD_CFGNAME(n),savedDomain||"");
  /* Call back immediately for instant switch */
  if (cb){ cb(savedDomain||""); }
  /* Background benchmark: find fastest domain and save for next time */
  SD_CHECK_DOMAIN(n,function(r){
    var sid=-1;
    var sid_time=60000;
    for (var i=0;i<r.length;i++){
      var w=r[i];
      if (w.st==2){
        if (w.tm<sid_time){
          sid=i;
          sid_time=w.tm;
        }
      }
    }
    if (sid>=0 && _domains){
      var bestDomain=(sid>0)?_domains[sid]:"";
      _JSAPI.storeSet(SD_CFGNAME(n),bestDomain);
      Log.i("DOMAIN","Auto-selected fastest: "+(_domains[sid])+" ("+sid_time+"ms)");
    }
  });
}
function SD_LOAD_DOMAIN(){
    __SD_DOMAIN=_JSAPI.storeGet(SD_CFGNAME(__SD),"");
    _JSAPI.setSdomain(__SD_DOMAIN);
    Log.i("DOMAIN", "SD Domain: "+__SD_DOMAIN);
    /* Check for pending toast from domain change before reload */
    var _pt=_JSAPI.storeGet("__pending_toast","");
    if (_pt){
      _JSAPI.storeDel("__pending_toast");
      setTimeout(function(){ _API.showToast(_pt); },500);
    }
}

