  provider:0,
  beforeChangeSource:function(cb){
    /* Show domain selection from miruro.com scraped domains with benchmarking */
    var domains = miruroDomains.getDomains();
    if (!domains || domains.length === 0) {
      domains = ['miruro.bz'];
    }

    /* Show benchmarking popup */
    $('popupcontainer').className='active';
    $('aboutpopup').className='active';
    $('popup_qrcode').onclick=null;
    $('popup_qrcode').innerHTML='Benchmarking domains...';
    $('popup_qrcode').style.display='';

    var res = [];
    var num = domains.length;

    function do_test(domain, i, tstart){
      res[i] = { dn: domain, st: 0, tm: -1 };
      var cleanDomain = domain.replace(/^https?:\/\//, '').replace(/^www\./, '');
      var url = 'https://www.' + cleanDomain + '/';
      $ap(url, function(r){
        var rv = { dn: domain, st: 1, tm: $tick() - tstart };
        if (r.ok) {
          rv.st = 2;
        }
        res[i] = rv;
        if (--num < 1) {
          /* All done - close popup and show results */
          app.settings.close_qrcode();
          $('popup_qrcode').innerHTML = '';

          var list_info = [];
          var sid = miruro.provider;
          /* Only auto-select fastest on first boot (no stored preference) */
          var hasUserChoice = _JSAPI.storeGet(miruro.providerKey(), "") !== "";
          var sid_time = 60000;
          for (var j = 0; j < res.length; j++) {
            var w = res[j];
            var tld = w.dn.replace(/^(www\.)?miruro\./, '.');
            var tx = special('miruro' + tld) + '<span class="value">' +
              (w.st == 2 ? ("OK - " + w.tm + "ms") : "ERROR") + '</span>';
            if (!hasUserChoice && w.st == 2 && w.tm < sid_time) {
              sid = j;
              sid_time = w.tm;
            }
            list_info.push(tx);
          }

          listOrder.showList(
            "Select Source Domain",
            list_info,
            sid,
            function(chval) {
              if (chval !== null) {
                var newProv = toInt(chval);
                var wsel = res[newProv];
                if (wsel.st != 2) {
                  if (!_API.confirmDialog("Domain Warning!!",
                    "Target Domain <b>" + wsel.dn + "</b> failed benchmark!!!<br>" +
                    "Do you want to continue?", true)) {
                    return;
                  }
                }
                miruro.provider = newProv;
                miruro.setProvider(newProv);
                cb();
              }
            },
            true,
            '',
            true
          );
        }
      }).timeout = 4000;
    }

    for (var i = 0; i < domains.length; i++) {
      do_test(domains[i], i, $tick());
    }
  },
