  /* Reuse miruro anilist view */
  getTooltip:function(id, cb, url, isview){
    if (!id){
      var ux=(url||'').split('#');
      id=ux[0];
    }
    var alId = (_API && _API.animeCatalogId) ? _API.animeCatalogId(id, url) : (id + '').replace(/\D+/g, '');
    var numId = parseInt(alId || '0', 10);
    var cacheKey = numId ? (numId + '') : (id + '');

    if (cacheKey in miruro.cache){
      if (miruro.cache[cacheKey]){
        var oval=JSON.parse(miruro.cache[cacheKey]);
        if ('url' in oval){
          requestAnimationFrame(function(){
            cb(oval);
          });
          return;
        }
      }
    }
    _MAL.alreq(`query ($id: Int) {
      Media(id:$id, type:ANIME, isAdult:false){
        id
        idMal
        title{
          romaji
          english
        }
        coverImage{
          large
        }
        status
        duration
        format
        episodes
        description
        bannerImage
        genres
        nextAiringEpisode {
          episode
        }
      }
    }`,{
          "id":numId || id
        },function(r){
      if (r){
        var o=null;
        var ostr=null;
        try{
          var m = r.data.Media;
          var kk=document.createElement('div');
          kk.innerHTML=m.description;

          var sumep = m.episodes;
          if (m.nextAiringEpisode){
            sumep=m.nextAiringEpisode.episode-1;
          }
          o={
            url:id,
            title:m.title.english?m.title.english:m.title.romaji,
            title_jp:m.title.romaji?m.title.romaji:m.title.english,
            synopsis:(kk.textContent+'').trim(),
            genres:[],
            genre:'',
            quality:null,
            ep:sumep,
            rating:'',
            ttid:id,
            poster:m.coverImage.large,
            tip:id,
            malId:m.idMal
          };
          o.genre=m.genres.join(", ");
          for (var i=1;i<m.genres.length;i++){
            try{
              o.genres.push({
                name:m.genres[i],
                val:m.genres[i].toLowerCase()
              });
            }catch(e){}
          }
          ostr=JSON.stringify(o);
          miruro.cache[id]=ostr;
        }catch(e){
          Log.w("MIRURO", e);
        }

        /* Fetch rating from Jikan/MAL API if malId is available */
        if (o && o.malId) {
          console.log('[ANIMETV][JIKAN] Fetching rating for malId=' + o.malId + ' title=' + o.title);
          var _jikanCacheKey = 'jikan_rating_' + o.malId;
          var _cachedRating = _JSAPI.storeGet(_jikanCacheKey, '');
          if (_cachedRating) {
            /* Use cached Jikan rating */
            console.log('[ANIMETV][JIKAN] Using cached rating: ' + _cachedRating);
            o.rating = _cachedRating;
            miruro.cache[id] = JSON.stringify(o);
            cb(JSON.parse(JSON.stringify(o)));
          } else {
            /* Fetch from Jikan API */
            var _cbObj = JSON.parse(JSON.stringify(o));
            cb(_cbObj);
            var _jikanUrl = 'https://api.jikan.moe/v4/anime/' + o.malId;
            console.log('[ANIMETV][JIKAN] Requesting: ' + _jikanUrl);
            $ap(_jikanUrl, function(jRes) {
              try {
                console.log('[ANIMETV][JIKAN] Response ok=' + jRes.ok + ' status=' + jRes.status);
                if (jRes.ok) {
                  var jd = JSON.parse(jRes.responseText);
                  if (jd && jd.data && jd.data.rating) {
                    var fullRating = jd.data.rating;
                    var shortRating = fullRating.split(' - ')[0].trim();
                    console.log('[ANIMETV][JIKAN] Got rating: ' + shortRating + ' (full: ' + fullRating + ')');
                    /* Update cache */
                    o.rating = shortRating;
                    miruro.cache[id] = JSON.stringify(o);
                    _JSAPI.storeSet(_jikanCacheKey, shortRating);
                    /* Update the popup rating badge if still visible */
                    console.log('[ANIMETV][JIKAN] onpopup=' + _MAL.onpopup + ' pop.rating=' + !!_MAL.pop.rating);
                    if (_MAL.onpopup && _MAL.pop.rating) {
                      _MAL.pop.var.rating = shortRating;
                      _MAL.pop.rating.setAttribute('data-rating', shortRating);
                      _MAL.popuprating(shortRating);
                      console.log('[ANIMETV][JIKAN] Badge updated to: ' + shortRating);
                    }
                  } else {
                    console.log('[ANIMETV][JIKAN] No rating in response for malId=' + o.malId);
                  }
                } else {
                  console.log('[ANIMETV][JIKAN] Request failed: ' + (jRes.responseText||'').substring(0,200));
                }
              } catch(je) {
                console.log('[ANIMETV][JIKAN] Error: ' + je);
              }
            });
          }
        } else {
          console.log('[ANIMETV][JIKAN] No malId available for id=' + id);
          cb(JSON.parse(ostr));
        }
        return;
      }
      cb(null);
    },1);
  },
