  listPrompt:function(title,list,sel,allowsel,nodim,selpos, cb){
    var d={
      'type':'list',
      'title':title,
      'list':list
    };
    if (sel!=undefined){
      if (Array.isArray(sel)){
        d.multi=sel;
      }
      else{
        d.sel=sel;
      }
    }
    if (allowsel){
      d.allowsel=true;
    }
    if (nodim){
      d.nodim=true;
    }
    if (selpos!=undefined){
      d.selpos=selpos;
    }

    if (cb){
      var cb_n = ++_API.asyncPrompCbn;
      _API.asyncPrompCbs["cb_"+cb_n]=cb;
      _JSAPI.asyncPrompt(JSON.stringify(d),cb_n);
      return;
    }
    return prompt(JSON.stringify(d));
  },

  textPrompt:function(title,message,ispin,maxlen,dv,cb,nohtml){
    if (_ISELECTRON){
      listOrder.showInput(title,message,ispin,maxlen,dv,cb,nohtml);
      return;
    }
    var d={
      'type':'text',
      'title':title,
      'message':message
    };
    if (!nohtml){
      d.html=true;
    }
    if (ispin){
      d.ispin=true;
    }
    if (maxlen){
      d.maxlen=maxlen;
    }
    if (dv){
      d.deval=dv;
    }
    if (!cb){
      var o=prompt(JSON.stringify(d));
      try{
        var k=JSON.parse(o);
        if ('value' in k){
          return k.value;
        }
      }catch(e){}
      return null;
    }
    var cb_n = ++_API.asyncPrompCbn;
    _API.asyncPrompCbs["cb_"+cb_n]=cb;
    _JSAPI.asyncPrompt(JSON.stringify(d),cb_n);
  },

