  animeId:function(url){
    if (__SD3){
      var ux=url.split('/');
      if (ux.length>1){
        var url_parse=ux[1].split('#');
        return url_parse[0];
      }
    }
    else if (__SD5){
      return url;
    }
    else if (__SD6){
      return kaas.getAnimeId(url);
    }
    else if (__SD7){
      return gojo.getAnimeId(url);
    }
    else if (__SD8 || __SD11 || __SD12){
      return (url+'').split('#')[0];
    }
    else if (__SD9){
      return anikoto.getAnimeId(url);
    }
    else if (__SD10){
      // TMDB/FMovies: URLs must match /movie/DIGITS or /tv/DIGITS
      // Reject stream URLs, empty strings, and any other non-TMDB format
      if (url && /^\/(movie|tv)\/\d+/.test(url)) return url.substring(1);
      return null;
    }
    else{
      var url_parse=url.split('/');
      if (url_parse.length>=5){
        return url_parse[4];
      }
    }
    return null;
  },

