  filterorigin:function(){
    if (__SD5)
      return __AFLIX.origin;
    else if (__SD6)
      return kaas.getFilterOrigin();
    else if (__SD7)
      return gojo.getFilterOrigin();
    else if (__SD8)
      return (typeof sourceProvider !== 'undefined') ? sourceProvider.getFilterOrigin() : null;
    else if (__SD11)
      return (typeof miruro !== 'undefined' && miruro.getFilterOrigin) ? miruro.getFilterOrigin() : null;
    else if (__SD12)
      return (typeof reanime !== 'undefined' && reanime.headers) ? reanime.headers() : null;
    else if (__SD9)
      return anikoto.getFilterOrigin();
    return null;
  },

  filterurl:function(q,genres,sort,page,ses,year){
    /*
      sort: 1.Relevant, 2.RecentUpdate
    */
    var uri='';
    if (__SD6){
      return kaas.getFilterUrl(q,genres,sort,page,ses,year);
    }
    else if (__SD7){
      return gojo.getFilterUrl(q,genres,sort,page,ses,year);
    }
    else if (__SD8 || __SD11 || __SD12){
      return '';
    }
    else if (__SD9){
      return anikoto.getFilterUrl(q,genres,sort,page,ses,year);
    }
    else if (!__SD3 && !__SD5){
      var qv=[];
      
      qv.push('keyword='+enc(q));
      // Wave & Anix
      if (ses){
        qv.push('season='+enc(ses));
      }
      if (year){
        qv.push('year='+enc(year));
      }

      if (!ses){
        if (genres){
          for (var i=0;i<genres.length;i++){
            var vl=genres[i];
            if (vl.charAt(0)=='_'){
              qv.push(enc('type[]')+'='+enc(_API.genres[vl]));
            }
            else{
              qv.push(enc('genre[]')+'='+enc(_API.genres[vl]));
            }
          }
          qv.push('genre_mode=and');
        }
        if (!pb.cfg_data.nonjapan){
          qv.push(enc('country[]')+'=120822');
        }
        qv.push(enc('language[]')+'=sub');
      }
      if (sort==1){
        qv.push('sort=most_relevance');
      }
      else if (sort==2){
        qv.push('sort=recently_updated');
      }

      if (page&&(page>1)){
        qv.push('page='+page);
      }
      uri='/filter?'+qv.join('&');
      console.log('[ANIMETV] FILTER: '+uri);
    }
    else if (__SD5){
      // ANIME FLIX
      var filters={};
      var qv=[];
      q=(q+'').toLowerCase();
      qv.push('query='+enc(q));
      if (genres){
        var gnr=[];
        var tps=[];
        for (var i=0;i<genres.length;i++){
          var vl=genres[i];
          if (vl.charAt(0)=='_'){
            tps.push(_API.genres_flix[vl]);
          }
          else{
            gnr.push(_API.genres_flix[vl]);
          }
        }
        if (tps.length>0){
          filters.type=tps;
        }
        if (gnr.length>0){
          filters.genre=gnr;
        }
      }
      var ksalt=q;
      if (q.length>3){
        ksalt=q.substring(0,3);
      }
      qv.push('limit=15');
      qv.push('filters='+enc(JSON.stringify(filters)));
      qv.push('k='+enc(__AFLIX.enc2(ksalt)));

      if (!q){
        uri='';
        if (filters.genre.length>0){
          uri='/__proxy/'+__AFLIX.ns+'/genres/'+(filters.genre[filters.genre.length-1])+'?page='+(page>1?page-1:0);
        }
      }
      else{
        uri='/__proxy/'+__AFLIX.ns+'/info/?'+qv.join('&');
      }
      console.log('[ANIMETV] FILTER: '+uri);
    }
    else{
      // HIANIME
      var qv=[];
      if (q){
        q=q.substring(0,100).trim();
      }
      qv.push('keyword='+enc(q?q:' '));
      console.log("[ANIMETV] FILTER URL REQ : "+JSON.stringify([q,genres,sort,page,ses,year]));
      if (!ses){
        if (genres){
          var tgenre=[];
          for (var i=0;i<genres.length;i++){
            var vl=genres[i];
            if (vl.charAt(0)=='_'){
              qv.push(enc('type')+'='+enc(_API.genres_hi[vl]));
            }
            else{
              tgenre.push(_API.genres_hi[vl]);
            }
          }
          if (tgenre.length>0){
            qv.push(enc('genres')+'='+enc(tgenre.join(',')));
          }
        }
        qv.push('language=1');
      }
      if (sort==1){
        qv.push('sort=default');
      }
      else if (sort==2){
        qv.push('sort=recently_updated');
      }
      else if (sort==2){
        qv.push('sort=default');
      }

      if (page&&(page>1)){
        qv.push('page='+page);
      }
      uri='/search?'+qv.join('&');
      console.log('[ANIMETV] FILTER: '+uri);
    }

    return uri;
  },

