    hidedesc: false,
    trailer: 1,
    server: 0,
    scale: 0,
    lang: '',
    alang: '',
    ccstyle: 300019,
    ccdelay: 0,
    bgimg: {},
    quality: 0,
    uifontsize: 1,
    seekvalue: 10,
    megaskip: false,
    megaskipduration: 30,
    autohide: 5,
    httpclient: 0,
    mirrorserver: 0,
    listprog: 0,
    prefstream: 1,
    autofallback: true,
    preloadep: true,
    hlsproxy: false,
