  anilist_yt: {
    initialized: false,
    cleanup: function (actvg) {
      if (!actvg) {
        actvg = app.anilist_yt.activeg;
        app.anilist_yt.activeg = null;
      }
      if (app.anilist_trailer_to) {
        clearTimeout(app.anilist_trailer_to);
        app.anilist_trailer_to = null;
      }
      if (actvg) {
        actvg.classList.remove('yt-playing');
        actvg._iframe_holder.innerHTML = '';
        actvg._ytiframe = null;
        actvg = null;
      }
    },
    init: function () {
      if (app.anilist_yt.initialized) {
        return;
      }
      app.anilist_yt.initialized = true;
      window.addEventListener('message', function (e) {
        // console.warn(e.data);
        if (_MAL.pop.var.ondetail) {
          var pd = JSON.parse(e.data);
          if (pd) {
            if ('vcmd' in pd) {
              _MAL.pop_detail_youtube_cb(pd.vcmd);
            }
          }
          return;
        }

        if (app.anilist_yt.activeg) {
          try {
            var pd = JSON.parse(e.data);
            if (pd) {
              if ('vcmd' in pd) {
                if (pd.vcmd == 'yt-play') {
                  app.anilist_yt.activeg.classList.add('yt-playing');
                } else if (pd.vcmd == 'yt-pause' || pd.vcmd == 'yt-end') {
                  app.anilist_yt.cleanup();
                }
              }
            }
          } catch (x) {}
        }
      });
    },
    activeg: null,
  },
