  settings_keycb: function (c) {
    if (app.ondonate) {
      if (c == KBACK || (c == KENTER && app.ondonate != 2)) {
        clk();
        app.settings.close_qrcode();
      }
      return;
    }

    var pc = app.settings.sel;
    var spc = app.settings.subsel;
    if (c == KBACK) {
      clk();
      app.settings.close();
    } else if (c == KENTER) {
      var gel = app.settings.menus[pc].P;
      var el = gel.children[spc];
      try {
        if (el.classList.contains('disabled')) {
          return;
        }
        clk();
        var action = el.getAttribute('action');
        var arg = el.getAttribute('arg');
        pb.action_handler(action, arg);
      } catch (e) {}
      app.settings.update(pc, spc);
      return;
    } else if (c == KUP) {
      var doNext = true;
      --spc;
      while (
        spc >= 0 &&
        app.settings.menus[pc].P.children[spc] &&
        app.settings.menus[pc].P.children[spc].style &&
        app.settings.menus[pc].P.children[spc].style.display == 'none'
      ) {
        --spc;
      }
      doNext = spc < 0 ? true : false;
      if (doNext) {
        if (--pc < 0) {
          pc = app.settings.menus.length - 1;
        }
        spc = -1;
      }
    } else if (c == KDOWN) {
      var doNext = true;
      ++spc;
      while (
        spc < app.settings.menus[pc].P.childElementCount &&
        app.settings.menus[pc].P.children[spc] &&
        app.settings.menus[pc].P.children[spc].style &&
        app.settings.menus[pc].P.children[spc].style.display == 'none'
      ) {
        ++spc;
      }
      doNext = spc >= app.settings.menus[pc].P.childElementCount ? true : false;
      if (doNext) {
        if (++pc >= app.settings.menus.length) {
          pc = 0;
        }
        spc = 0;
      }
    } else if (c == KLEFT || c == KPGUP) {
      if (--pc < 0) {
        pc = app.settings.menus.length - 1;
      }
      spc = -1;
      app.settings.update(pc, spc);
      spc = 0;
    } else if (c == KRIGHT || c == KPGDOWN) {
      if (++pc >= app.settings.menus.length) {
        pc = 0;
      }
      spc = -1;
      app.settings.update(pc, spc);
      spc = 0;
    }
    if (app.settings.sel != pc || app.settings.subsel != spc) {
      clk();
      app.settings.update(pc, spc);
    }
  },
