  allist_search:function(q,cb,page,perpage,minimal,mywatch){
    q=utfascii(q);
    _MAL.alreq((minimal?`query ($search: String, $page: Int, $perPage: Int) {
      Page(page: $page, perPage: $perPage) {
        pageInfo {
          perPage
          hasNextPage
          currentPage
        }
        media(sort: SEARCH_MATCH, type: ANIME, search: $search){
          id
          idMal
          status
          title{
            romaji
            english
          }
          episodes
          mediaListEntry{
            id,
            progress,
            status
          }
        }
      }
    }`:
    `query ($search: String, $page: Int, $perPage: Int) {
      Page(page: $page, perPage: $perPage) {
        pageInfo {
          perPage
          hasNextPage
          currentPage
        }
        media(sort: SEARCH_MATCH, type: ANIME, search: $search){
          id
          idMal
          title{
            romaji
            english
          }
          coverImage{
            large
            medium
            color
          }
          status
          duration
          format
          seasonYear
          season
          isAdult
          nextAiringEpisode {
            episode
          }
          episodes
          description
          bannerImage
          averageScore
          favourites
          popularity
          trending
          genres
          startDate {
            year
            month
            day
          }
          endDate {
            year
            month
            day
          }
          studios {
            edges{
              isMain
              node{
                name
              }
            }
          }
          mediaListEntry{
            id,
            progress,
            status
          }
          synonyms
          source
          countryOfOrigin
          reviews {
            edges {
              node {
                id
                summary
                rating
                score
              }
            }
          }
          trailer {
            id
            site
            thumbnail
          }
        }
      }
    }`),{
      "page":page?page:1,
      "perPage":perpage?perpage:10,
      "search":q
    },function(v){
      if (v){
        if (v.data.Page.media){
          var srcq=[
            utfascii(q),
            slugString(q)
          ];
          var srcf=[
            utfascii,
            slugString
          ];
          for (var j=0;j<2 && !v.match;j++){
            for (var i=0;i<v.data.Page.media.length;i++){
              var med=v.data.Page.media[i];
              var s1=med.title.english;
              var s2=med.title.romaji;
              var ms=med.status;
              if (ms=="FINISHED" || ms=="RELEASING" || ms=="HIATUS" || (mywatch&&(ms=="NOT_YET_RELEASED")) ){
                if (s1 && (srcf[j](s1)==srcq[j])){
                  v.match=JSON.parse(JSON.stringify(med));
                  break;
                }
                else if (s2 && (srcf[j](s2)==srcq[j])){
                  v.match=JSON.parse(JSON.stringify(med));
                  break;
                }
              }
            }
          }
          /* force first result */
          if (!v.match && mywatch && (v.data.Page.media.length>0)){
            v.match=JSON.parse(JSON.stringify(v.data.Page.media[0]));
          }
        }
        cb(v);
        return;
      }
      cb(null);
    });
  },
