  login:function(isanilist,logintype){
    if (_MAL.token && !isanilist){
      _API.confirm("Logout MAL",
        "Are you sure you want to logout MyAnimeList integration?",
        function(cnf){
          if (cnf){
            _JSAPI.storeDel(_API.user_prefix+"mal_auth");
            _API.showToast("MyAnimeList logout sucessfull...");
            _API.reload();
          }
      });
    }
    else if (_MAL.altoken && isanilist){
      _API.confirm("Logout AniList",
        "Are you sure you want to logout AniList integration?",
        function(cnf){
          if (cnf){
            _JSAPI.storeDel(_API.user_prefix+"anilist_auth");
            _API.showToast("AniList logout sucessfull...");
            _API.reload();
          }
      });
    }
    else{
      app.settings.open_qrcode(
        '<span class="z-loader z-small"></span><br>Please Wait..',
        null,
        true
      );
      var lid='';
      var lstate=0;
      var root_url = _JSAPI.storeGet(
        isanilist ? 'anilist_auth_url' : 'mal_auth_url',
        isanilist
          ? 'https://animetv-auth.jitendhull.workers.dev/anilist'
          : 'https://animetv-auth.jitendhull.workers.dev/mal'
      ).replace(/\/+$/, '');
      function delLid(){
        var uriv=root_url+'/check?lid='+lid+"&del="+$tick();
        $ap(uriv, function(r){});
      }
      function waitLogin(){
        var uriv=root_url+'/check?lid='+lid+"&"+$tick();
        $ap(uriv, function(r){
          if (app.ondonate){
            if (r.ok){
              try{
                var k=JSON.parse(r.responseText);
                console.log("[ANIMETV] MAL RECHECK = "+r.responseText+" / "+uriv);
                if ((k.st==1)&&(lstate==0)){
                  lstate=1;
                  app.settings.open_qrcode(
                    '<span class="z-loader z-small"></span><br>'+
                    (isanilist?'Please finish AniList authorization':'Please finish MAL authorization'),
                    null,
                    true
                  );
                }
                else if (k.st==2){
                  app.settings.close_qrcode();
                  _MAL.onlogin(JSON.parse(r.responseText),isanilist?2:1);
                  return;
                }
              }catch(e){}
            }
            /* retry */
            setTimeout(waitLogin,2000);
          }
          else{
            delLid();
          }
        });
      }
      function showQr(){
        lstate=0;
        app.settings.open_qrcode(
          isanilist?'Scan QR and login to AniList in your phone':'Scan QR and login to MAL in your phone',
          root_url+"/login?lid="+lid,
          true
        );
        waitLogin();
      }
      var genRetries=0;
      function genLid(){
        if (isanilist){
          lid='AL'+$tick()+'Y';
        }
        else{
          lid='MAL'+$tick()+'L';
        }
        var uri=root_url+'/check?lid='+lid+"&"+$tick();
        $ap(uri, function(r){
          if (app.ondonate){
            if (r.ok){
              try{
                var k=JSON.parse(r.responseText);
                console.log("[ANIMETV] MAL CHECK = "+r.responseText);
                if (k.st==0){
                  showQr();
                  return;
                }
              }catch(e){}
            }
            genRetries++;
            if (genRetries > 4){
              app.settings.close_qrcode();
              _API.showToast(isanilist ? "AniList auth service unavailable" : "MAL auth service unavailable");
              return;
            }
            /* retry */
            setTimeout(genLid,2000);
          }else{
            delLid();
          }
        });
      }
      genLid();
    }
  },
  onlogin:function(d,tp){
    if (d){
      if (!tp){
        d.tk=d.access_token;
        d.ex=d.expires_in;
      }
      if (('tk' in d) && ('ex' in d) && d.tk && d.ex){
        var dt={
          access_token:d.tk,
          exp:d.ex+$time(),
          expires_in:d.ex,
          user:d.user
        };

        if (tp==2){
          // Fetch AniList username via Viewer query if not provided
          if (!dt.user) {
            _MAL.altoken = dt.access_token;
            _MAL.alreq(`query { Viewer { name } }`, {}, function(v){
              if (v && v.data && v.data.Viewer && v.data.Viewer.name){
                dt.user = v.data.Viewer.name;
              }
              _JSAPI.storeSet(_API.user_prefix+"anilist_auth",JSON.stringify(dt));
              console.log("[ANIMETV] ANILIST-ONLOGIN: "+JSON.stringify(dt));
              _API.showToast("AniList login sucessfull...");
              _API.reload();
            });
          } else {
            _JSAPI.storeSet(_API.user_prefix+"anilist_auth",JSON.stringify(dt));
            console.log("[ANIMETV] ANILIST-ONLOGIN: "+JSON.stringify(dt));
            _API.showToast("AniList login sucessfull...");
            _API.reload();
          }
        }
        else{
          _JSAPI.storeSet(_API.user_prefix+"mal_auth",JSON.stringify(dt));
          console.log("[ANIMETV] MAL-ONLOGIN: "+JSON.stringify(dt));
          _API.showToast("MyAnimeList login sucessfull...");
          _API.reload();
        }
      }
      else if (tp==2){
        _API.showToast("AniList Login Failed");
      }
      else{
        _API.showToast("MyAnimeList Login Failed"+(('message' in d)?": "+d.message:""));
      }
    }
  },
