      begin: $('mvplay_begin'),
      resume: $('mvplay_resume'),
      resume_ep: $('mvplay_resume_ep'),
      resume_text: $('mvplay_resume_text'),
      progh: $('mvplay_resume_progh'),
      prog: $('mvplay_resume_prog'),
