              var incomingTdurIsPlaceholder = !tdur || tdur < MIN_PLAUSIBLE_DUR_SEC;
              var effectiveDur = incomingTdurIsPlaceholder ? estimatedDur : tdur;

              // [TRAKT-RESUME-DIAG] resolved duration used in the seek math
