      health._loadErrorCount = 0;
      /* Reset seek recovery grace state on successful recovery */
      health._seekRecoveryErrorCount = 0;
      if (health._seekRecoveryGraceTimer) {
        clearTimeout(health._seekRecoveryGraceTimer);
        health._seekRecoveryGraceTimer = null;
      }

