    if (!stream || !stream.url) {
      health._recovering = false;
      try { _JSAPI.showToast('Recovery failed - no stream URL'); } catch(e) {}
      return;
    }
    var nativeUrl = _PB._nativePlaybackUrl({
      url: stream.url,
      type: stream.type || (stream.url.indexOf('.m3u8') !== -1 ? 'hls' : 'mp4'),
      provider: stream.provider || data.provider || (pb._fmovies_data && pb._fmovies_data.provider) || ''
    });

    console.log('[STREAM-HEALTH] Recovery success! New URL: ' + nativeUrl.substring(0, 80));
    try { _JSAPI.showToast('Reconnected successfully'); } catch(e) {}

    pb._fmovies_data.url = stream.url;
    pb._fmovies_data.type = stream.type || pb._fmovies_data.type;
    pb.init_video_player_url(nativeUrl);

    setTimeout(function() {
      _JSAPI.videoSetPosition(resumePos);
      health._recovering = false;
    }, 1500);
