  /* ═══════════════════════════════════════════════════════════════════════════
   * WASM MODULE MANAGEMENT
   * Download, patch, instantiate the Videasy WASM module for decryption.
   * ═══════════════════════════════════════════════════════════════════════════ */

  /**
   * Ensure the WASM module is loaded and ready.
   * Downloads module.wasm, applies the verified-guard bypass patch, instantiates it.
   * Caches the instance for subsequent calls.
   * 
   * @param {function} cb - Callback(err, instance)
   */
  _ensureWasm: function(cb) {
    /* Already loaded */
    if (_Videasy._wasmInstance) {
      cb(null, _Videasy._wasmInstance);
      return;
    }

    /* Loading in progress — queue callback */
    if (_Videasy._wasmLoading) {
      _Videasy._wasmCallbacks.push(cb);
      return;
    }

    _Videasy._wasmLoading = true;
    _Videasy._wasmCallbacks = [cb];

    var finishAll = function(err, inst) {
      _Videasy._wasmLoading = false;
      var cbs = _Videasy._wasmCallbacks;
      _Videasy._wasmCallbacks = [];
      for (var i = 0; i < cbs.length; i++) {
        try { cbs[i](err, inst); } catch(e) {}
      }
    };

    console.log('[Videasy] Loading WASM module...');

    /* Fetch the WASM binary via the Java pipe (avoids CORS issues) */
    var wasmUrl = 'https://' + _JSAPI.dns() + '/__videasy_pipe/wasm';

    var xhr = new XMLHttpRequest();
    xhr.open('GET', wasmUrl, true);
    xhr.responseType = 'arraybuffer';
    xhr.timeout = 30000;

    xhr.onload = function() {
      if (xhr.status !== 200 || !xhr.response) {
        console.error('[Videasy] WASM fetch failed: HTTP ' + xhr.status);
        finishAll(new Error('WASM fetch failed'), null);
        return;
      }

      try {
        var buf = new Uint8Array(xhr.response);
        console.log('[Videasy] WASM downloaded: ' + buf.length + ' bytes');

        /* Apply the verified-guard bypass patch.
         * Find pattern: 0x23 0x46 0x45 0x04 0x40
         *   = global.get 70; i32.eqz; if void
         * Replace first 2 bytes with: 0x41 0x01
         *   = i32.const 1 (so eqz(1)=0, if-block skipped → abort bypassed) */
        var patchCount = 0;
        for (var i = 0; i < buf.length - 5; i++) {
          if (buf[i] === 0x23 && buf[i+1] === 0x46 &&
              buf[i+2] === 0x45 && buf[i+3] === 0x04 && buf[i+4] === 0x40) {
            buf[i] = 0x41;    // i32.const
            buf[i+1] = 0x01;  // 1
            patchCount++;
          }
        }
        console.log('[Videasy] WASM patched: ' + patchCount + ' guard(s) bypassed');

        if (patchCount === 0) {
          console.warn('[Videasy] No verified guards found — WASM may have changed structure');
        }

        /* Instantiate the patched WASM */
        var imports = {
          env: {
            seed: function() { return Date.now() * Math.random(); },
            abort: function(msg, file, line, col) {
              throw new Error('[WASM abort] ' + line + ':' + col);
            }
          }
        };

        WebAssembly.compile(buf.buffer).then(function(module) {
          return WebAssembly.instantiate(module, imports);
        }).then(function(instance) {
          _Videasy._wasmInstance = instance;
          console.log('[Videasy] WASM instantiated OK, exports: ' + Object.keys(instance.exports).join(', '));
          finishAll(null, instance);
        }).catch(function(e) {
          console.error('[Videasy] WASM instantiation failed: ' + e.message);
          finishAll(new Error('WASM instantiate: ' + e.message), null);
        });
      } catch(e) {
        console.error('[Videasy] WASM processing error: ' + e.message);
        finishAll(new Error('WASM process: ' + e.message), null);
      }
    };

    xhr.onerror = function() {
      console.error('[Videasy] WASM XHR network error');
      finishAll(new Error('WASM network error'), null);
    };
    xhr.ontimeout = function() {
      console.error('[Videasy] WASM XHR timeout');
      finishAll(new Error('WASM timeout'), null);
    };
    xhr.send();
  },

