        var nextIdx = (currentIdx + 1) % servers.length;
        setServerName(servers[nextIdx].name);
        if (typeof _API !== 'undefined' && _API.showToast) {
          _API.showToast('Server: ' + servers[nextIdx].name);
        }
        if (cb) cb(true);
